import{_ as s,c as t,o as l,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易集说","description":"周易集说 - 周易集说","frontmatter":{"title":"周易集说","description":"周易集说 - 周易集说"},"headers":[],"relativePath":"zh/classics/jishuo/001.md","filePath":"zh/classics/jishuo/001.md"}'),n={name:"zh/classics/jishuo/001.md"};function o(i,a,c,p,d,u){return l(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易集说",tabindex:"-1"},[r("周易集说 "),e("a",{class:"header-anchor",href:"#周易集说","aria-label":"Permalink to “周易集说”"},"​")],-1),e("p",null,"钦定四库全书经部一",-1),e("p",null,"易类提要",-1),e("p",null,"臣 等谨案：周易集说四十卷，宋俞琰撰。琰字玉吾，吴人。读易三十余年，未尝倦辍。其书集诸家之说，用功阅二十八年，凡四易稿始成。同时汉东孟淳、单父李克宽、钱唐白珽、西秦张瑛、同郡颜尧焕、干文传诸辈，皆推而重之。琰尝与孟淳讲坤之六二，谓六二既中且正，是以其德直方，惟从乾阳之大，不习坤阴之小，故无不利。又谓彖传「刚柔上下」，言来不言往，皆以两卦相并而取义。其发诸儒所未发，多类于此。琰又有读易须知、易图纂要、易经考证、易传考证、六十四卦图、古占法、卦爻象占分类、易图合璧连珠、易外传诸书，今皆不传。然其自为后序称诸编皆旧所作，将毁之，而儿辈以为可惜，又略加改窜，而存于后。则旧刻本附此数书，今佚之也。乾隆四十六年十月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。周易集说序：",-1),e("p",null,"周易集说者，集诸说之善而为之说也。曷为善？能明三圣人之本旨则善也。夫易始作于伏羲，仅有六十四卦之画，而未有辞。文王作上下经，乃始有辞。孔子作十翼，其辞乃备。当知辞本于象，象本于画，有画斯有象，有象斯有辞。易之理尽在于画，讵可舍六画之象，而专论辞之理哉！舍画而玩辞，舍象而穷理，辞虽明，理虽通，非易也。汉去古未远，诸儒训解多论象数，盖亦有所本。至魏王弼以老庄之虚无倡于前，普、韩康伯又和于后，圣人之本旨遂晦。沿袭至于唐，诸儒皆宗之。太宗诏名儒定九经正义，于易则取王、韩，而孔颖达辈以当时所尚，故虽其说未尽善，亦必为之回护。由是二三百年间，皆以虚无为高。至宋，濂、洛诸公彬彬辈出，一埽虚无之弊，圣人之本旨始明。奈何世之尚占而宗邵康节者，则以义理为虚文；尚辞而宗程伊川者，则以象数为末技。而邵、程之学分为两家，羲画、周经亦为两途，遂使学者莫之适从。逮夫紫阳朱子本义之作，发邵、程之未发，辞必本于画，理不外于象，圣人之本旨于是乎大明焉。琰幼承父师面命，首读朱子本义，次读程传，长与朋友讲明，则又有程、朱二公所未言者，于心盖不能无疑。乃历考诸家易说，摭其英华，萃为一书，名曰大易会要，凡一百三十卷。不揣固陋，遂自至元甲申集诸说之善而为之说，凡四十卷，因名之曰周易集说云。元贞丙申五月六日，林屋山人俞琰序。",-1)])])}const _=s(n,[["render",o]]);export{m as __pageData,_ as default};
